require_relative "meta/schema"

# The loading model for 2020-12 schema documents, generated by
# `rake meta:generate` from the vendored metaschema (D20). One
# recursive class: every schema node in a document loads into a
# Schematrix::Meta::Schema instance.
module Schematrix
  # Entry point namespace for the generated loading model; the class
  # itself lives in meta/schema.rb.
  module Meta
  end
end
